const raw = $json.body ?? $json;
const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
const b = parsed?.data ?? parsed?.input ?? parsed ?? {};
const value = (keys) => keys.map((key) => b[key]).find((item) => item !== undefined && item !== null && item !== '');
const normalized = { product: value(['product', 'product_name', 'productName', 'product_query', 'productQuery']), origin_country: value(['origin_country', 'originCountry', 'origin']), destination_country: value(['destination_country', 'destinationCountry', 'destination', 'dest']), quantity_kg: value(['quantity_kg', 'quantityKg', 'quantity']), target_price_usd: value(['target_price_usd', 'targetPriceUSD', 'target_price', 'price_usd']), trade_value_usd: value(['trade_value_usd', 'tradeValueUSD', 'trade_value']), certifications: value(['certifications', 'required_certifications']), trade_flow: value(['trade_flow', 'tradeFlow']), regime: value(['regime', 'strategy']) };
if (normalized.target_price_usd === undefined && normalized.trade_value_usd !== undefined && Number(normalized.quantity_kg) > 0) normalized.target_price_usd = Number(normalized.trade_value_usd) / Number(normalized.quantity_kg);
const required = ['product', 'origin_country', 'destination_country', 'quantity_kg', 'target_price_usd'];
const missing = required.filter((key) => normalized[key] === undefined || normalized[key] === null || normalized[key] === '');
if (missing.length) throw new Error(`Missing required fields: ${missing.join(', ')}. Send product, origin_country, destination_country, quantity_kg, and target_price_usd.`);
const quantity = Number(normalized.quantity_kg);
const price = Number(normalized.target_price_usd);
if (!Number.isFinite(quantity) || quantity <= 0 || !Number.isFinite(price) || price <= 0) throw new Error('quantity_kg and target_price_usd must be positive numbers');
return [{ json: { product: String(normalized.product), origin_country: String(normalized.origin_country).toUpperCase(), destination_country: String(normalized.destination_country).toUpperCase(), quantity_kg: quantity, target_price_usd: price, certifications: Array.isArray(normalized.certifications) ? normalized.certifications : [], trade_flow: normalized.trade_flow || 'Export', regime: normalized.regime || 'balanced' } }];
